package com.fangfang.forum;
import java.util.*;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.boot.autoconfigure.condition.ConditionalOnExpression;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
@RestController @RequestMapping("/api") @ConditionalOnExpression("'${app.service:all}' == 'all' or '${app.service:all}' == 'content'")
public class ContentController {
 final JdbcTemplate db;final Support support;final PostMapper mapper;final ForumCache cache;
 static final List<String> CATEGORIES=List.of("校园交流","学习求助","校园资讯","二手闲置");
 public ContentController(JdbcTemplate db,Support support,PostMapper mapper,ForumCache cache){this.db=db;this.support=support;this.mapper=mapper;this.cache=cache;}
 public record PostInput(@NotBlank @Size(max=150)String title,@NotBlank @Size(max=20000)String body,@NotBlank String category){}
 public record CommentInput(@NotBlank @Size(max=2000)String body){}
 @GetMapping("/categories")public List<String> categories(){return CATEGORIES;}
 @GetMapping("/posts")public Map<String,Object> posts(@RequestParam(defaultValue="")@Size(max=200)String q,@RequestParam(defaultValue="")String category,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="10")int size,@RequestParam(defaultValue="false")boolean bookmarks,@AuthenticationPrincipal Jwt jwt){page=Math.max(1,Math.min(page,100000));size=Math.max(1,Math.min(50,size));if(q.length()>200)throw new IllegalArgumentException("搜索词过长");if(bookmarks&&jwt==null)throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.UNAUTHORIZED,"请先登录查看收藏");String uid=jwt==null?"":String.valueOf(support.user(jwt.getSubject()).get("id"));return Map.of("items",mapper.list(q,category,(page-1)*size,size,uid,bookmarks),"total",mapper.count(q,category,uid,bookmarks),"page",page,"size",size);}
 @GetMapping("/posts/{id}")public Map<String,Object> post(@PathVariable String id,@AuthenticationPrincipal Jwt jwt){var p=cache.post(id);db.update("UPDATE posts SET views=views+1 WHERE id=?",id);cache.bump(id,1);Map<String,Object> result=new LinkedHashMap<>(p);result.put("views",((Number)p.get("views")).longValue()+1);result.put("likes",db.queryForObject("SELECT COUNT(*) FROM reactions WHERE post_id=? AND kind='like' AND active=TRUE",Long.class,id));result.put("bookmarks",db.queryForObject("SELECT COUNT(*) FROM reactions WHERE post_id=? AND kind='bookmark' AND active=TRUE",Long.class,id));result.put("comments",db.queryForList("SELECT c.*,u.username FROM comments c JOIN users u ON u.id=c.user_id WHERE c.post_id=? ORDER BY c.created_at,c.id",id));if(jwt!=null){String uid=String.valueOf(support.user(jwt.getSubject()).get("id"));result.put("myReactions",db.queryForList("SELECT kind,active FROM reactions WHERE post_id=? AND user_id=?",id,uid));}return result;}
 @PostMapping("/posts")@Transactional public Map<String,String> create(@Valid @RequestBody PostInput input,@AuthenticationPrincipal Jwt jwt){support.rate("post:"+jwt.getSubject(),5,60);validateCategory(input.category());String id=support.id();db.update("INSERT INTO posts(id,user_id,title,body,category) VALUES (?,?,?,?,?)",id,support.user(jwt.getSubject()).get("id"),input.title().trim(),input.body(),input.category());support.audit(jwt.getSubject(),"发布帖子",id);return Map.of("id",id);}
 @PutMapping("/posts/{id}")@Transactional public Map<String,String> edit(@PathVariable String id,@Valid @RequestBody PostInput input,@AuthenticationPrincipal Jwt jwt){validateCategory(input.category());var user=support.user(jwt.getSubject());var rows=db.queryForList("SELECT * FROM posts WHERE id=? FOR UPDATE",id);if(rows.isEmpty())throw new IllegalArgumentException("帖子不存在");if(!rows.get(0).get("user_id").equals(user.get("id")))throw new org.springframework.security.access.AccessDeniedException("只能编辑自己的帖子");db.update("UPDATE posts SET title=?,body=?,category=?,updated_at=CURRENT_TIMESTAMP WHERE id=?",input.title().trim(),input.body(),input.category(),id);cache.evict(id);support.audit(jwt.getSubject(),"编辑帖子",id);return Map.of("message","已保存");}
 @DeleteMapping("/posts/{id}")@Transactional public Map<String,String> remove(@PathVariable String id,@AuthenticationPrincipal Jwt jwt){var user=support.user(jwt.getSubject());var rows=db.queryForList("SELECT user_id FROM posts WHERE id=? FOR UPDATE",id);if(rows.isEmpty())throw new IllegalArgumentException("帖子不存在");if(!rows.get(0).get("user_id").equals(user.get("id")))throw new org.springframework.security.access.AccessDeniedException("只能删除自己的帖子");db.update("UPDATE posts SET status='deleted' WHERE id=?",id);cache.evict(id);support.audit(jwt.getSubject(),"删除自己的帖子",id);return Map.of("message","已删除");}
 @PostMapping("/posts/{id}/comments")@Transactional public Map<String,String> comment(@PathVariable String id,@Valid @RequestBody CommentInput input,@AuthenticationPrincipal Jwt jwt){support.rate("comment:"+jwt.getSubject(),15,60);cache.requirePublished(id);String cid=support.id();db.update("INSERT INTO comments(id,post_id,user_id,body) VALUES (?,?,?,?)",cid,id,support.user(jwt.getSubject()).get("id"),input.body());cache.bump(id,4);cache.evict(id);support.audit(jwt.getSubject(),"发表评论",cid);return Map.of("id",cid);}
 void validateCategory(String category){if(!CATEGORIES.contains(category))throw new IllegalArgumentException("分类无效");}
}
